template<class TV0, class F0> Array<int32_t> SortedIndices(Array<TV0> xs, F0 lessOrEqual)
{
    int32_t n = ToCount(xs);
    Buffer<int32_t> src = make_buffer<int32_t>(n);
    int32_t i = 0;
    while (((i <= n) ? (!(i == n)) : false))
    {
        src = Set(src, i, i);
        i = (i + 1);
    }
    Buffer<int32_t> dst = make_buffer<int32_t>(n);
    int32_t width = 1;
    while (((width <= n) ? (!(width == n)) : false))
    {
        int32_t lo = 0;
        while (((lo <= n) ? (!(lo == n)) : false))
        {
            int32_t mid = (((lo + width) <= n) ? (lo + width) : n);
            int32_t hi = ((((lo + width) + width) <= n) ? ((lo + width) + width) : n);
            int32_t a = lo;
            int32_t b = mid;
            int32_t k = lo;
            while (((k <= hi) ? (!(k == hi)) : false))
            {
                if ((mid <= a))
                {
                    dst = Set(dst, k, At(src, b));
                    b = (b + 1);
                }
                else
                {
                    if ((hi <= b))
                    {
                        dst = Set(dst, k, At(src, a));
                        a = (a + 1);
                    }
                    else
                    {
                        if ((lessOrEqual)(At(xs, At(src, a)), At(xs, At(src, b))))
                        {
                            dst = Set(dst, k, At(src, a));
                            a = (a + 1);
                        }
                        else
                        {
                            dst = Set(dst, k, At(src, b));
                            b = (b + 1);
                        }
                    }
                }
                k = (k + 1);
            }
            lo = ((lo + width) + width);
        }
        Buffer<int32_t> merged = dst;
        dst = src;
        src = merged;
        width = (width + width);
    }
    return Freeze(src);
}

